 if ( AH -> tableDataId [ te -> dumpId ] != 0 ) {
 TocEntry * ted = AH -> tocsByDumpId [ AH -> tableDataId [ te -> dumpId ] ] ;
 ted -> reqs = 0 ;
 }
 }

