 if ( ( sr_diff > LOW_SR_DIFF_TRHESH ) ) {
 sr_diff = MIN ( sr_diff , SR_DIFF_MAX ) ;
 sr_decay = 1.0 - ( SR_DIFF_PART * sr_diff ) - ( MOTION_AMP_PART * motion_amplitude_factor ) - ( INTRA_PART * pcnt_intra ) ;
 }
