 }
 if ( ! ( subblkpat & ( 1 << ( 3 - j ) ) ) && ! skip_block ) {
 if ( i == 1 ) v -> vc1dsp . vc1_inv_trans_4x4_dc ( dst + ( j & 1 ) * 4 + ( j & 2 ) * 2 * linesize , linesize , block + off ) ;
