 avi -> stream_index = - 1 ;
 return 0 ;
 }
 pos_min = pos ;
 for ( i = 0 ;
 i < s -> nb_streams ;
 i ++ ) {
 AVStream * st2 = s -> streams [ i ] ;
 AVIStream * ast2 = st2 -> priv_data ;
 ast2 -> packet_size = ast2 -> remaining = 0 ;
 if ( ast2 -> sub_ctx ) {
 seek_subtitle ( st , st2 , timestamp ) ;
 continue ;
 }
 if ( st2 -> nb_index_entries <= 0 ) continue ;
 index = av_index_search_timestamp ( st2 , av_rescale_q ( timestamp , st -> time_base , st2 -> time_base ) * FFMAX ( ast2 -> sample_size , 1 ) , flags | AVSEEK_FLAG_BACKWARD | ( st2 -> codecpar -> codec_type != AVMEDIA_TYPE_VIDEO ? AVSEEK_FLAG_ANY : 0 ) ) ;
 if ( index < 0 ) index = 0 ;
 ast2 -> seek_pos = st2 -> index_entries [ index ] . pos ;
 pos_min = FFMIN ( pos_min , ast2 -> seek_pos ) ;
 }
 for ( i = 0 ;
 i < s -> nb_streams ;
 i ++ ) {
 AVStream * st2 = s -> streams [ i ] ;
 AVIStream * ast2 = st2 -> priv_data ;
 if ( ast2 -> sub_ctx || st2 -> nb_index_entries <= 0 ) continue ;
 index = av_index_search_timestamp ( st2 , av_rescale_q ( timestamp , st -> time_base , st2 -> time_base ) * FFMAX ( ast2 -> sample_size , 1 ) , flags | AVSEEK_FLAG_BACKWARD | ( st2 -> codecpar -> codec_type != AVMEDIA_TYPE_VIDEO ? AVSEEK_FLAG_ANY : 0 ) ) ;
 if ( index < 0 ) index = 0 ;
 while ( ! avi -> non_interleaved && index > 0 && st2 -> index_entries [ index - 1 ] . pos >= pos_min ) index -- ;
 ast2 -> frame_offset = st2 -> index_entries [ index ] . timestamp ;
 }
 if ( avio_seek ( s -> pb , pos_min , SEEK_SET ) < 0 ) {
 av_log ( s , AV_LOG_ERROR , "Seek failed\n" ) ;
 return - 1 ;
 }
 avi -> stream_index = - 1 ;
 avi -> dts_max = INT_MIN ;
 return 0 ;
 }

