 }
 pcmd . keyword = tokens [ 0 ] ;
 pcmd . nargs = 0 ;
 for ( i = 0 ;
 i < MAXARGS && xcmd -> arg [ i ] != NO ;
 i ++ ) {
 if ( ( i + 1 ) >= ntok ) {
