 printusage ( xcmd , stderr ) ;
 return ;
 }
 break ;
 }
 if ( ( xcmd -> arg [ i ] & OPT ) && ( * tokens [ i + 1 ] == '>' ) ) break ;
 if ( ! getarg ( tokens [ i + 1 ] , ( int ) xcmd -> arg [ i ] , & pcmd . argval [ i ] ) ) return ;
 pcmd . nargs ++ ;
 }
 i ++ ;
 if ( i < ntok && * tokens [ i ] == '>' ) {
