 break ;
 case PARTITION_SPLIT : subsize = get_subsize ( bsize , PARTITION_SPLIT ) ;
 encode_sb_rt ( cpi , tile , tp , mi_row , mi_col , output_enabled , subsize , pc_tree -> split [ 0 ] ) ;
