 return - 1 ;
 }
 if ( get_cseq ( msg ) -> method_id == METHOD_ACK || get_cseq ( msg ) -> method_id == METHOD_CANCEL ) {
 LM_DBG ( "no pre-transaction management for ACK or CANCEL\n" ) ;
 return - 1 ;
 }
