 }
 memset ( _tmx_proc_ptran , 0 , sizeof ( pretran_t ) ) ;
 _tmx_proc_ptran -> pid = my_pid ( ) ;
 }
 dsize = scallid . len + scseqnum . len + scseqmet . len + sftag . len + 4 ;
 if ( likely ( vbr != NULL ) ) {
 svbranch = vbr -> value ;
 trim ( & svbranch ) ;
 dsize += svbranch . len + 1 ;
 }
 if ( dsize < 256 ) dsize = 256 ;
 tmx_pretran_unlink ( ) ;
 if ( dsize > _tmx_proc_ptran -> dbuf . len ) {
