 cat4_prob = vp9_cat4_prob ;
 cat5_prob = vp9_cat5_prob ;
 cat6_prob = vp9_cat6_prob ;
 }
 # else cat1_prob = vp9_cat1_prob ;
 cat2_prob = vp9_cat2_prob ;
 cat3_prob = vp9_cat3_prob ;
 cat4_prob = vp9_cat4_prob ;
 cat5_prob = vp9_cat5_prob ;
 cat6_prob = vp9_cat6_prob ;
 # endif while ( c < max_eob ) {
